mapper.select:
WITH active_tags AS ( SELECT t.tagname FROM ( SELECT rds.tagname, rds.value, ROW_NUMBER() OVER (PARTITION BY rds.tagname ORDER BY rds.ts DESC) as rn FROM TB_RAWDATA_SUNSI rds INNER JOIN TB_PEAK_TAG_INF pti ON rds.tagname = pti.PWQ_TAG WHERE pti.mntr_yn = '1' AND pti.IS_ALL = '0' AND rds.ts >= DATE_SUB(NOW(), INTERVAL 5 MINUTE)
AND pti.CLSFC = #{zone_code}
) t WHERE rn = 1 AND value >= 0.01 ), period_data AS ( SELECT rd.tagname, rd.ts, rd.value, ROW_NUMBER() OVER (PARTITION BY rd.tagname ORDER BY rd.ts ASC) as rn_start, ROW_NUMBER() OVER (PARTITION BY rd.tagname ORDER BY rd.ts DESC) as rn_end FROM TB_RAWDATA rd INNER JOIN active_tags at ON rd.tagname = at.tagname WHERE 1=1
AND rd.ts >= concat(#{start_date},' 00:00:00') AND rd.ts <= concat(#{end_date},' 23:59:00')
AND rd.ts >= concat(#{start_date},'-01 00:00:00') AND rd.ts <= concat(#{end_date},'-31 23:59:00')
AND rd.ts >= concat(#{start_date},'-01-01 00:00:00') AND rd.ts <= concat(#{end_date},'-12-31 23:59:00')
) SELECT DATE_FORMAT(e.ts,'%Y-%m-%d %H') DATE_FORMAT(e.ts,'%Y-%m-%d') DATE_FORMAT(e.ts,'%Y-%m') DATE_FORMAT(e.ts,'%Y') AS x, fc.FAC_NAME as fac_name, fc.fac_code as fac_code, pti.PWQ_TAG as tagname, ROUND( AVG( CASE WHEN TIMESTAMPDIFF(MINUTE, s.ts, e.ts) > 0 THEN (CAST(e.value AS DECIMAL(20,4)) - CAST(s.value AS DECIMAL(20,4))) * CAST(pti.PWQ_UNIT_VALUE AS DECIMAL(20,4)) / TIMESTAMPDIFF(MINUTE, s.ts, e.ts) ELSE 0 END ), 2 ) AS y FROM (SELECT tagname, ts, value FROM period_data WHERE rn_start = 1) s INNER JOIN (SELECT tagname, ts, value FROM period_data WHERE rn_end = 1) e ON s.tagname = e.tagname INNER JOIN TB_PEAK_TAG_INF pti ON s.tagname = pti.PWQ_TAG INNER JOIN TB_FAC fc ON pti.HMI_TAG_DSC = fc.FAC_NAME GROUP BY fac_code ORDER BY x, tagname

WITH raw_data AS ( SELECT rd.tagname, rd.ts, rd.value, pti.CLSFC, pti.PWI_UNIT_VALUE, LAG(rd.ts) OVER (PARTITION BY rd.tagname ORDER BY rd.ts) AS prev_ts, LAG(rd.value) OVER (PARTITION BY rd.tagname ORDER BY rd.ts) AS prev_value FROM TB_RAWDATA rd JOIN TB_PEAK_TAG_INF pti ON rd.tagname = pti.PWI_TAG WHERE pti.MNTR_YN = '1' AND pti.IS_ALL = '1' AND pti.CLSFC IS NOT NULL AND pti.CLSFC != '' AND rd.ts >= DATE_SUB(DATE_FORMAT(now(), '%Y-%m-%d 00:00:00'), INTERVAL 1 DAY) AND rd.ts <= DATE_FORMAT(now(), '%Y-%m-%d 23:59:59')
AND pti.CLSFC = #{zone_code}
), base_diff AS ( SELECT tagname, ts, CLSFC, CASE WHEN RIGHT(tagname, 3) = 'IKW' THEN ROUND(value * PWI_UNIT_VALUE, 6) WHEN prev_ts IS NULL OR prev_value IS NULL THEN 0 WHEN value < prev_value THEN 0 WHEN (value - prev_value) > 2000 THEN NULL ELSE ROUND((value - prev_value) * PWI_UNIT_VALUE, 6) END AS raw_y FROM raw_data ), filled_diff AS ( SELECT tagname, ts, CLSFC, raw_y, COUNT(raw_y) OVER (PARTITION BY tagname ORDER BY ts ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS grp FROM base_diff ), diff_data AS ( SELECT tagname, ts, CLSFC, COALESCE(raw_y, MAX(raw_y) OVER (PARTITION BY tagname, grp)) AS y FROM filled_diff ) SELECT DATE_FORMAT(ts, '%Y-%m-%d %H:%i') AS x, CLSFC AS zone_name, ROUND(SUM(y), 2) AS y FROM diff_data WHERE ts >= DATE_FORMAT(now(), '%Y-%m-%d 00:00:00') AND ts <= DATE_FORMAT(now(), '%Y-%m-%d 23:59:59') GROUP BY ts, CLSFC ORDER BY zone_name, ts
